// Adds MW Chat's own Android code to a project freshly generated by Bubblewrap
// from twa-manifest.json:
//   node native/prepare.mjs <generated-project-dir>
// It copies the alert-sound code and sounds, registers the mwchat://tone link,
// and points the build at Google's mirror of Maven Central.
import { cpSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const project = process.argv[2];
if (!project) throw new Error("Usage: node native/prepare.mjs <generated-project-dir>");
const main = join(project, "app/src/main");

cpSync(join(here, "java"), join(main, "java"), { recursive: true });
cpSync(join(here, "res"), join(main, "res"), { recursive: true });

const manifestPath = join(main, "AndroidManifest.xml");
let manifest = readFileSync(manifestPath, "utf8");
if (!manifest.includes(".ToneActivity")) {
  const anchor = '        <service\n            android:name=".DelegationService"';
  if (!manifest.includes(anchor)) throw new Error("DelegationService not found: was enableNotifications on?");
  manifest = manifest.replace(
    anchor,
    `        <!-- MW Chat's Settings opens mwchat://tone?id=... to set the alert sound. -->
        <activity
            android:name=".ToneActivity"
            android:exported="true"
            android:excludeFromRecents="true"
            android:noHistory="true"
            android:taskAffinity=""
            android:theme="@android:style/Theme.Translucent.NoTitleBar">
            <intent-filter>
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="mwchat" android:host="tone" />
            </intent-filter>
        </activity>

${anchor}`,
  );
  writeFileSync(manifestPath, manifest);
}

const gradlePath = join(project, "build.gradle");
const gradle = readFileSync(gradlePath, "utf8").replace(
  /google\(\)\n(\s*)jcenter\(\)/g,
  'google()\n$1maven { url "https://maven-central.storage-download.googleapis.com/maven2/" }',
);
writeFileSync(gradlePath, gradle);
console.log("MW Chat native code added to", project);
